-- VERSION 83: additive payroll schema repair + two explicitly marked sample months.
-- Run this entire file in the EXISTING Supabase project's SQL Editor, then click Run.
-- Preserves legacy payroll_runs/payroll_lines and all business transactions/settings.
-- Re-running does not duplicate or overwrite the sample records.
begin;
create table if not exists public.payroll_employees (
 id uuid primary key default gen_random_uuid(), data jsonb,
 version integer not null default 1, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id)
);
create table if not exists public.payroll_leave_records (
 id uuid primary key default gen_random_uuid(), data jsonb,
 version integer not null default 1, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id)
);
create table if not exists public.payroll_runs (
 id uuid primary key default gen_random_uuid(), data jsonb,
 version integer not null default 1, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id)
);
create table if not exists public.operational_reports (
 id uuid primary key default gen_random_uuid(), data jsonb,
 version integer not null default 1, created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(), updated_by uuid references public.profiles(id)
);
do $$ declare t text; begin
 foreach t in array array['payroll_employees','payroll_leave_records','payroll_runs','operational_reports'] loop
 execute format('drop trigger if exists guard_record82 on public.%I',t);
 execute format('drop trigger if exists guard_record83 on public.%I',t);
 execute format('alter table public.%I add column if not exists data jsonb',t);
 execute format('alter table public.%I add column if not exists version integer not null default 1',t);
 execute format('alter table public.%I add column if not exists created_at timestamptz not null default now()',t);
 execute format('alter table public.%I add column if not exists updated_at timestamptz not null default now()',t);
 execute format('alter table public.%I add column if not exists updated_by uuid references public.profiles(id)',t);
 execute format('update public.%I set updated_at=coalesce(updated_at,created_at,now()),version=coalesce(version,1) where updated_at is null or version is null',t);
 end loop;
end $$;
-- Keep original required period columns and synchronize them for new application snapshots.
alter table public.payroll_runs add column if not exists period_start date;
alter table public.payroll_runs add column if not exists period_end date;
alter table public.payroll_runs add column if not exists status text not null default 'draft';
alter table public.payroll_runs add column if not exists created_by uuid references public.profiles(id);
alter table public.payroll_runs add column if not exists approved_by uuid references public.profiles(id);
create unique index if not exists payroll_employee_code_unique on public.payroll_employees(lower(data->>'code')) where coalesce(data->>'code','')<>'';
