 for person in select value from jsonb_array_elements(sample->'employees') loop
  if not exists(select 1 from public.payroll_employees where lower(data->>'code')=lower(person->'data'->>'code')) then
   insert into public.payroll_employees(id,data,version,updated_by) values((person->>'id')::uuid,person->'data',1,admin_id) on conflict(id) do nothing;
  end if;
 end loop;
 for run in select value from jsonb_array_elements(sample->'runs') loop
  mapped='[]'::jsonb;
  for line in select value from jsonb_array_elements(run->'data'->'rows') loop
   select id into employee_id from public.payroll_employees where lower(data->>'code')=lower(line->'employee'->>'code') limit 1;
   mapped=mapped||jsonb_build_array(jsonb_set(line,'{employeeId}',to_jsonb(employee_id::text)));
  end loop;
  run=jsonb_set(run,'{data,rows}',mapped);
  if not exists(select 1 from public.payroll_runs where data->>'reference'=run->'data'->>'reference') then
   insert into public.payroll_runs(id,data,version,period_start,period_end,status,created_by,updated_by)
   values((run->>'id')::uuid,run->'data',1,((run->'data'->>'month')||'-01')::date,(((run->'data'->>'month')||'-01')::date+interval '1 month - 1 day')::date,'draft',admin_id,admin_id) on conflict(id) do nothing;
  end if;
 end loop;
end $seed83$;
create or replace function public.guard_payroll_report_record83() returns trigger language plpgsql set search_path=public as $$
begin
 if not public.is_admin() then raise exception 'Administrator access required'; end if;
 if new.data is null then
  if tg_op='UPDATE' and old.data is not null then raise exception 'Cannot remove an application payroll snapshot'; end if;
  new.updated_at=now();new.updated_by=auth.uid();return new;
 end if;
 if jsonb_typeof(new.data)<>'object' then raise exception 'Invalid record data'; end if;
 if tg_op='UPDATE' then
  if new.version<>old.version+1 then raise exception 'Record version conflict'; end if;
  if tg_table_name='payroll_runs' and old.data->>'status'='finalized' then raise exception 'Finalized payroll is immutable. Create a new correction run.'; end if;
  new.created_at=old.created_at;
 end if;

 if tg_table_name='payroll_employees' and (coalesce(trim(new.data->>'code'),'')='' or coalesce(trim(new.data->>'name'),'')='') then raise exception 'Employee code and name are required'; end if;
 if tg_table_name='payroll_runs' then
  if coalesce(new.data->>'status','') not in ('draft','finalized') or coalesce(new.data->>'month','') !~ '^\d{4}-(0[1-9]|1[0-2])$' or jsonb_typeof(new.data->'rows') is distinct from 'array' then raise exception 'Invalid payroll run'; end if;
  if new.data->>'status'='finalized' and (jsonb_typeof(new.data->'results') is distinct from 'array' or jsonb_typeof(new.data->'config') is distinct from 'object' or jsonb_array_length(new.data->'results')=0) then raise exception 'Finalized payroll requires calculated results and applied rules'; end if;
 end if;
 if tg_table_name='payroll_runs' then
  new.period_start=((new.data->>'month')||'-01')::date;
  new.period_end=(new.period_start+interval '1 month - 1 day')::date;
  new.status=new.data->>'status';
  if tg_op='INSERT' then new.created_by=auth.uid(); end if;
  if new.status='finalized' then
   if coalesce((new.data->>'isSample')::boolean,false) then raise exception 'Examples cannot be finalized as actual payroll'; end if;
   new.approved_by=auth.uid();
  end if;
 end if;
 if tg_table_name='payroll_leave_records' then
  if coalesce(new.data->>'status','') not in ('pending','approved','cancelled') or not exists(select 1 from public.payroll_employees where id::text=new.data->>'employeeId') then raise exception 'Invalid leave record or employee'; end if;
  if exists(select 1 from public.payroll_runs r cross join lateral jsonb_array_elements(r.data->'rows') employee where r.data->>'status'='finalized' and r.data->>'month'=new.data->>'month' and employee->>'employeeId'=new.data->>'employeeId') then raise exception 'Payroll for this employee and month is finalized; retain the leave record and document corrections in a later period'; end if;
  if tg_op='UPDATE' and exists(select 1 from public.payroll_runs r cross join lateral jsonb_array_elements(r.data->'rows') employee where r.data->>'status'='finalized' and r.data->>'month'=old.data->>'month' and employee->>'employeeId'=old.data->>'employeeId') then raise exception 'Leave included in finalized payroll is immutable'; end if;
 end if;
 if tg_table_name='operational_reports' and coalesce(new.data->>'kind','') not in ('subuser','finance') then raise exception 'Invalid report type'; end if;
 new.updated_at=now();new.updated_by=auth.uid();return new;
end $$;
do $$ declare t text;begin
 foreach t in array array['payroll_employees','payroll_leave_records','payroll_runs','operational_reports'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon, authenticated',t);
 execute format('grant select, insert, update on public.%I to authenticated',t);
 execute format('drop policy if exists admin_records82 on public.%I',t);
 execute format('create policy admin_records82 on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t);
 execute format('drop policy if exists admin_only83 on public.%I',t);
 execute format('create policy admin_only83 on public.%I as restrictive for all to authenticated using(public.is_admin()) with check(public.is_admin())',t);
 execute format('drop trigger if exists guard_record83 on public.%I',t);
 execute format('create trigger guard_record83 before insert or update on public.%I for each row execute function public.guard_payroll_report_record83()',t);
 end loop;
end $$;
notify pgrst, 'reload schema';
commit;
-- The result below confirms completion. Expect 7 requested sample employees and 2 sample runs
-- (employee count may be lower if matching real employees already existed and were reused).
select 'Payroll repair complete — click Reload Records in Payroll' as result,
 (select count(*) from public.payroll_employees where coalesce((data->>'isSample')::boolean,false)) as sample_employees,
 (select count(*) from public.payroll_runs where data->>'reference' in ('SAMPLE-PAY-2026-08','SAMPLE-PAY-2026-09')) as sample_months,
 (select count(*) from information_schema.columns where table_schema='public' and table_name='payroll_runs' and column_name in ('data','version','updated_at','updated_by')) as required_columns;
